    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 79-year-old female named Grace with heart failure, diabetes, and moderate dementia is being discharged from the hospital to a skilled nursing facility for post-acute rehabilitation. The discharge team is implementing a structured care transitions program. Which of the following is the most important element of safe hospital-to-SNF care transition to prevent early readmission?', '["Using verbal-only handoff communication to the SNF nursing staff to save time, as written documentation is not required by The Joint Commission", "A structured medication reconciliation (accurate and complete transfer of the medication list), a detailed discharge summary transmitted to the SNF before or at the time of transfer, clear communication of pending tests and follow-up needs, and a follow-up phone call within 48\u201372 hours", "Scheduling the patient''s first post-discharge physician follow-up appointment in 3 months, as stable patients do not require early reassessment", "Providing the patient with a thick discharge folder of educational pamphlets and assuming the patient will manage their own care transition independently", "Instructing the SNF to restart all home medications from memory without providing a written reconciled medication list"]'::jsonb, 1, '**Hospital-to-SNF care transitions** are high-risk periods for medication errors, communication failures, and early readmission. Evidence-based transition elements include: (1) **Medication reconciliation** — the single most important element; errors are present in up to 60% of post-discharge medication lists; (2) **Complete discharge summary** — transferred to the SNF in advance of or at the time of admission; should include diagnosis, treatment, pending results, follow-up plans; (3) **Early follow-up** — phone call within 48–72 hours; physician visit within 7 days; (4) **Patient/family education** — teach-back method for warning signs; (5) **Care transition models** (Care Transitions Intervention by Coleman; BOOST; Project RED) have been shown to reduce 30-day readmissions by 20–30%. The CMS Transitional Care Management (TCM) billing codes incentivize structured post-discharge follow-up. (Ref: Hazzard''s Ch. 17; AGS Geriatrics At Your Fingertips; UWorld Step 2 CK)'),
    (v_topic_id, 'A 97-year-old male named Lawrence with heart failure, diabetes, and moderate dementia is being discharged from the hospital to a skilled nursing facility for post-acute rehabilitation. The discharge team is implementing a structured care transitions program. Which of the following is the most important element of safe hospital-to-SNF care transition to prevent early readmission?', '["Using verbal-only handoff communication to the SNF nursing staff to save time, as written documentation is not required by The Joint Commission", "Providing the patient with a thick discharge folder of educational pamphlets and assuming the patient will manage their own care transition independently", "Scheduling the patient''s first post-discharge physician follow-up appointment in 3 months, as stable patients do not require early reassessment", "A structured medication reconciliation (accurate and complete transfer of the medication list), a detailed discharge summary transmitted to the SNF before or at the time of transfer, clear communication of pending tests and follow-up needs, and a follow-up phone call within 48\u201372 hours", "Instructing the SNF to restart all home medications from memory without providing a written reconciled medication list"]'::jsonb, 3, '**Hospital-to-SNF care transitions** are high-risk periods for medication errors, communication failures, and early readmission. Evidence-based transition elements include: (1) **Medication reconciliation** — the single most important element; errors are present in up to 60% of post-discharge medication lists; (2) **Complete discharge summary** — transferred to the SNF in advance of or at the time of admission; should include diagnosis, treatment, pending results, follow-up plans; (3) **Early follow-up** — phone call within 48–72 hours; physician visit within 7 days; (4) **Patient/family education** — teach-back method for warning signs; (5) **Care transition models** (Care Transitions Intervention by Col